import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DlhmXL2o.js";const p=JSON.parse('{"title":"What counts as a breaking change","description":"","frontmatter":{},"headers":[],"relativePath":"learn/explanation/breaking-changes.md","filePath":"learn/explanation/breaking-changes.md","lastUpdated":1786297412000}'),n={name:"learn/explanation/breaking-changes.md"};function s(i,e,h,c,d,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-counts-as-a-breaking-change" tabindex="-1">What counts as a breaking change <a class="header-anchor" href="#what-counts-as-a-breaking-change" aria-label="Permalink to &quot;What counts as a breaking change&quot;">​</a></h1><p>Most libraries have one thing a release can break: the API you write against. Argot has three, and knowing all three tells you how much risk an upgrade actually carries.</p><h2 id="_1-the-source-api" tabindex="-1">1. The source API <a class="header-anchor" href="#_1-the-source-api" aria-label="Permalink to &quot;1. The source API&quot;">​</a></h2><p>Everything <code>public</code> in <code>argot-core</code> and <code>argot-annotations</code> — the declarations you type. Renaming <code>OptionBuilder.required()</code>, changing a parameter&#39;s type, removing an overload. This is the surface every library has, and the obvious one.</p><h2 id="_2-the-generated-code-contract" tabindex="-1">2. The generated-code contract <a class="header-anchor" href="#_2-the-generated-code-contract" aria-label="Permalink to &quot;2. The generated-code contract&quot;">​</a></h2><p>The declarations that <em>generated</em> parsers call: <code>CommandSpec</code>, the three <code>ParamSpec</code> constructors, <code>ArgotEngine.parse</code>, and <code>ParsedValues.value</code> / <code>valueOrNull</code> / <code>flag</code> / <code>list</code>.</p><p>You never write these by hand, so they look like internals. They are not. The processor and the core are separate artifacts with separate version numbers, and nothing stops a build resolving <code>argot-processor</code> 0.1.1 alongside <code>argot-core</code> 0.2.0 — a transitive dependency is enough. Code emitted by the older processor still has to compile and link against the newer core.</p><p>A change here breaks builds that never mention the changed declaration, and the error points at generated code you did not write. That is why these declarations are <code>public</code> and version-controlled rather than hidden behind <code>internal</code>: mismatched versions of the two artifacts have to keep working together.</p><h2 id="_3-observable-cli-behaviour" tabindex="-1">3. Observable CLI behaviour <a class="header-anchor" href="#_3-observable-cli-behaviour" aria-label="Permalink to &quot;3. Observable CLI behaviour&quot;">​</a></h2><p>Parsing semantics and the layout of <code>--help</code>.</p><p>This one breaks nothing at compile time, which is what makes it easy to under-weigh. CLI programs get tested by asserting on their output, so somewhere a test contains the exact <code>--help</code> text Argot rendered. Changing the column at which help text aligns, the wording of an error, or whether <code>--flag --flag</code> is tolerated will break that test on an upgrade you expected to be routine.</p><p>The first two surfaces are checked mechanically: the public ABI of each published module is recorded and verified on every build, so neither can change without that being deliberate. The third has no such check, and is held in place by tests over rendered help and error messages.</p><h2 id="what-this-means-for-version-numbers" tabindex="-1">What this means for version numbers <a class="header-anchor" href="#what-this-means-for-version-numbers" aria-label="Permalink to &quot;What this means for version numbers&quot;">​</a></h2><p>While Argot is <code>0.x</code>, breaking changes are allowed in a minor release, and each one is listed in the <a href="https://github.com/Derrick-Mwendwa/argot/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a> with before and after. A patch release leaves all three surfaces alone.</p><p>After <code>1.0.0</code>, anything that removes or renames a declaration, changes a signature, alters the generated-code contract, or changes parsing or <code>--help</code> in a way that could break working code requires a major bump.</p><h2 id="dependency-updates-are-not-automatically-patches" tabindex="-1">Dependency updates are not automatically patches <a class="header-anchor" href="#dependency-updates-are-not-automatically-patches" aria-label="Permalink to &quot;Dependency updates are not automatically patches&quot;">​</a></h2><p>The question is whether the update changes what a consumer must have or do.</p><p>The Gradle wrapper, test libraries and the publishing plugin are build-only — a consumer cannot observe them, so they are patches. KotlinPoet is compile-time inside the processor, so it is a patch unless the generated output changes.</p><p>Kotlin and KSP are not build-only. Annotation-style users must apply a matching Kotlin and KSP version in their own build, so raising Argot&#39;s raises their floor. That is a minor release.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="https://github.com/Derrick-Mwendwa/argot/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">Changelog</a> — what actually changed in each release.</li><li><a href="./two-styles">Two styles, one engine</a> for why surface 2 exists at all.</li></ul>',21)])])}const g=a(n,[["render",s]]);export{p as __pageData,g as default};
